def min_clear_rate(queues, minutes):
    lo, hi = 1, max(queues)  # the largest queue always fits
    while lo < hi:
        mid = (lo + hi) // 2
        if sum((q + mid - 1) // mid for q in queues) <= minutes:
            hi = mid
        else:
            lo = mid + 1
    return lo

