def min_clear_rate(queues, minutes):
    lo, hi = 1, max(queues)
    while lo < hi:
        mid = (lo + hi) // 2
        if sum(max(1, q // mid) for q in queues) <= minutes:
            hi = mid
        else:
            lo = mid + 1
    return lo

def min_clear_rate(queues, minutes):
    lo, hi = 1, max(queues) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if sum((q + mid - 1) // mid for q in queues) <= minutes:
            hi = mid
        else:
            lo = mid + 1
    return lo
